 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;DungeonPrototype d;RetroDungeonWallComposer composer;DungeonSaveData original;RetroDungeonSettings originalSettings,settings;readonly List<string> results=new List<string>();public bool Done{get;private set;}public string Summary{get;private set;}
 object Get(string name){return typeof(DungeonPrototype).GetField(name,F).GetValue(d);}object Call(string name,params object[] args){return typeof(DungeonPrototype).GetMethod(name,F).Invoke(d,args);}void Check(bool yes,string text){results.Add((yes?"PASS ":"FAIL ")+text);}void Warp(int x,int y,int heading=0){Call("WarpPlayer",new Vector2Int(x,y),heading);}RetroDungeonPipe Pipe{get{return composer.GetComponentInChildren<RetroDungeonPipe>();}}
