 public void Run(){StartCoroutine(Checks());}
 IEnumerator Checks(){composer=UnityEngine.Object.FindFirstObjectByType<RetroDungeonWallComposer>();d=composer.dungeon;original=d.CaptureDungeonSave();originalSettings=composer.settings;settings=Instantiate(originalSettings);composer.settings=settings;
 try{
