  var visited=new HashSet<Vector2Int>();var queue=new Queue<Vector2Int>();queue.Enqueue(map.startCell);visited.Add(map.startCell);var dirs=new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right};while(queue.Count>0){var at=queue.Dequeue();foreach(var direction in dirs){var next=at+direction;if(map.IsFloor(next)&&visited.Add(next))queue.Enqueue(next);}}int floors=0;foreach(var row in rows)foreach(var ch in row)if(ch=='.')floors++;Check(visited.Count==floors,"All test sections connected by BFS");bool room=true;for(int y=6;y<=12;y++)for(int x=2;x<=8;x++)room&=map.IsFloor(new Vector2Int(x,y));Check(room,"First room has clear 7x7 floor");room=true;for(int y=10;y<=16;y++)for(int x=11;x<=17;x++)room&=map.IsFloor(new Vector2Int(x,y));Check(room,"Pipe room has clear 7x7 floor");
  var scale=EnemySpaceLayout.Corridor(DungeonVisualSettings.Current,EnemySizeSettings.Current);Check(Mathf.Approximately(d.RetroCellSize,scale.x)&&Mathf.Approximately(d.RetroWallHeight,scale.y),"Original grid and camera scale reused");Check(composer.WallRuns>0&&composer.ElementCount>50&&composer.PipeCount>3,"Varied layer compositions and physical pipes generated");int hash=composer.CompositionHash,count=composer.ElementCount;composer.Build();yield return null;yield return null;Check(hash==composer.CompositionHash&&count==composer.ElementCount,"Same seed reproduces exact composition");int renderers=composer.GetComponentsInChildren<Renderer>().Length;yield return null;yield return null;Check(renderers==composer.GetComponentsInChildren<Renderer>().Length,"No decorative regeneration per frame");
  bool clear=true;foreach(var collider in composer.transform.Find("Retro wall compositions").GetComponentsInChildren<Collider>())clear&=!collider.enabled;Check(clear,"Decorative layers and pipes have no blocking colliders");bool ceiling=true;foreach(Transform child in composer.transform)if(child.name=="Ceiling")ceiling&=child.GetComponent<Renderer>().sharedMaterial.shader.name!="Codebound/Retro Dungeon Layer";Check(ceiling,"Original digital ceiling material retained");var lighting=d.RetroView.GetComponent<DungeonCorridorLighting>();Check(lighting.settings.fogColor==settings.distanceLight&&settings.distanceLight==Color.white,"Distance fades into white light");Check(d.RetroView.GetComponent<HelmetCRTController>()!=null,"Existing CRT renderer and HUD retained");
  Warp(5,1);yield return (IEnumerator)Call("Move",1,0);Check(d.RetroPlayerCell==new Vector2Int(5,2),"Original controller advances exactly one grid cell");yield return (IEnumerator)Call("Move",0,1);Check((int)Get("heading")==1,"Original turn remains exactly 90 degrees");yield return (IEnumerator)Call("Move",0,-1);Check((int)Get("heading")==0,"Consecutive reverse turn remains aligned");
  var doors=(Dictionary<string,DungeonDoor>)Get("mapDoors");var door=doors["retro.sections.door"];door.SetClosedImmediately();Check(door.Blocks((Vector3)Call("World",new Vector2Int(10,11)),(Vector3)Call("World",new Vector2Int(10,12))),"Section door blocks closed passage");door.SetOpenImmediately();Check(!door.Blocks((Vector3)Call("World",new Vector2Int(10,11)),(Vector3)Call("World",new Vector2Int(10,12))),"Section door opens normally without decorative obstruction");
  Warp(5,2);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot("Captures/RetroDungeonExperiment/Corridor.png");Warp(5,7);d.RetroView.transform.rotation=Quaternion.Euler(0,35,0);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot("Captures/RetroDungeonExperiment/Room.png");
  var layerMaterials=new Dictionary<Material,float>();foreach(var renderer in composer.transform.Find("Retro wall compositions").GetComponentsInChildren<Renderer>()){var material=renderer.sharedMaterial;if(material!=null&&!layerMaterials.ContainsKey(material))layerMaterials[material]=material.GetFloat("_Parallax");}yield return new WaitForEndOfFrame();var withParallax=ReadWorld();foreach(var pair in layerMaterials)pair.Key.SetFloat("_Parallax",0);yield return null;yield return new WaitForEndOfFrame();var flat=ReadWorld();int changed=0;for(int i=0;i<flat.Length;i++)if(Mathf.Abs(flat[i].r-withParallax[i].r)+Mathf.Abs(flat[i].g-withParallax[i].g)+Mathf.Abs(flat[i].b-withParallax[i].b)>12)changed++;foreach(var pair in layerMaterials)pair.Key.SetFloat("_Parallax",pair.Value);Check(changed>30,"GPU world output changes with per-layer parallax: "+changed+" pixels");
