  var saved=d.CaptureDungeonSave();DungeonSaveStore.Write(saved,0,"Retro test");d.RestoreDungeonSave(DungeonSaveStore.Read(0));yield return null;Check(d.CaptureEnemyProgression().Count==1&&d.RetroPipeAttempts("retro.pipe.demo")==1,"Save/load restores pipe enemy without duplication");
  yield return (IEnumerator)Call("Move",1,0);yield return new WaitForSecondsRealtime(1);Check(d.LaboratoryBattle,"Pipe enemy initiates normal proximity encounter");Check(((List<int>)Get("encounter")).Count==1,"Combat uses one existing enemy and normal encounter flow");
  d.RestoreDungeonSave(original);var stage=(GameObject)Get("battleStage");if(stage!=null)stage.SetActive(false);settings.spawnProbability=0;composer.Build();yield return null;yield return null;Warp(17,12);yield return new WaitForSecondsRealtime(.2f);Check(d.CaptureEnemyProgression().Count==0&&d.RetroPipeAttempts("retro.pipe.demo")==1,"Zero probability consumes one activation without spawning");
  Summary=results.FindAll(v=>v.StartsWith("PASS ")).Count+" passed / "+results.FindAll(v=>v.StartsWith("FAIL ")).Count+" failed";
 }finally{d.RestoreDungeonSave(original);var stage=(GameObject)Get("battleStage");if(stage!=null)stage.SetActive(false);composer.settings=originalSettings;composer.Build();Destroy(settings);File.WriteAllLines("Tests/RetroDungeonResults.txt",results);Done=true;Debug.Log("Retro experiment: "+Summary);}
